package com.aigora.tutororchestrator.application.usecase;
import com.aigora.tutororchestrator.application.contracts.command.*;import com.aigora.tutororchestrator.application.error.*;import com.aigora.tutororchestrator.application.ports.*;import com.aigora.tutororchestrator.application.contracts.result.*;import com.aigora.tutororchestrator.domain.model.*;import java.time.*;
public final class CompleteExerciseUseCase {
 private final LearningSessionRepository repo;private final SessionEventPublisher publisher;private final LifecycleTelemetrySink telemetry;private final Clock clock;
 public CompleteExerciseUseCase(LearningSessionRepository repo,SessionEventPublisher publisher,LifecycleTelemetrySink telemetry,Clock clock){this.repo=repo;this.publisher=publisher;this.telemetry=telemetry;this.clock=clock;}
 public SessionResult<LearningSession> execute(CompleteExerciseCommand c){long started=System.nanoTime();var opt=repo.findById(c.sessionId());if(opt.isEmpty())return fail(c,SessionErrorCode.SESSION_NOT_FOUND,"Learning session not found",started,c.expectedVersion());var session=opt.get();if(session.hasProcessed(c.commandId())){telemetry.record("complete-exercise",session.id(),session.version(),"deduplicated",System.nanoTime()-started);return new SessionSuccess<>(session.copy());}if(!session.version().equals(c.expectedVersion()))return fail(c,SessionErrorCode.VERSION_CONFLICT,"Session version mismatch",started,session.version());var expected=session.version();try{session.completeExercise(c.attemptId(),c.exerciseId(),c.commandId(),c.correlationId(),c.causationId(),Instant.now(clock));var events=session.drainEvents();repo.update(session,expected);try{publisher.publish(events);}catch(RuntimeException e){return fail(c,SessionErrorCode.EVENT_PUBLICATION_FAILURE,e.getMessage(),started,session.version());}telemetry.record("complete-exercise",session.id(),session.version(),"success",System.nanoTime()-started);return new SessionSuccess<>(session.copy());}catch(SessionVersionConflictException e){return fail(c,SessionErrorCode.VERSION_CONFLICT,e.getMessage(),started,session.version());}catch(RuntimeException e){return fail(c,SessionErrorCode.INVALID_TRANSITION,e.getMessage(),started,session.version());}}
 private SessionResult<LearningSession> fail(CompleteExerciseCommand c,SessionErrorCode code,String msg,long started,com.aigora.tutororchestrator.domain.valueobjects.SessionVersion v){telemetry.record("complete-exercise",c.sessionId(),v,"failure:"+code,System.nanoTime()-started);return UseCaseSupport.failure(code,msg==null?code.name():msg);}
}
